{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table snitch_db.maplemonk.channel_targets_tracking as WITH Base_Data AS ( SELECT lower(L_1_CATEGORY) AS L1_category, lower(category) category, CHANNELS, TRY_TO_NUMBER(REPLACE(qty, \',\', \'\')) AS target_qty, TRY_TO_NUMBER(REPLACE(revenue, \',\', \'\')) AS target_revenue, TRY_TO_DOUBLE(REPLACE(gm_, \'%\', \'\')) AS GM_target, month, COALESCE( TRY_TO_DATE(TRIM(month), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(month) || \'-01\', \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(month), \'MON-YY\'), TRY_TO_DATE(TRIM(month), \'MONTH-YY\'), TRY_TO_DATE(TRIM(month) || \'-2026\', \'MONTH-YYYY\'), TRY_TO_DATE(TRIM(month) || \'-2026\', \'MON-YYYY\') ) AS month_date FROM snitch_db.maplemonk.channel_targets_sheet1 ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LONG TAIL\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'PLUS\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LUXE\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'SNITCH\' THEN l1_category END), MIN(l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN category END), MIN(category) ) AS category, MAX(cogs) AS sku_cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ), sales_actual_base AS ( SELECT DATE_TRUNC(\'MONTH\', h.date) AS month_date, lower(m.l1_category) l1_category, lower(m.category) category, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'MP\' WHEN type = \'Store\' THEN \'Offline\' END AS channels, SUM(h.gross_quantity) AS sales_qty, SUM(h.gross_sales) AS sales_revenue, SUM(h.gross_quantity * COALESCE(m.sku_cogs, 0)) AS cogs FROM snitch_db.maplemonk.horizontal_sales_categories h LEFT JOIN meta_map m ON UPPER( IFF( UPPER(REPLACE(h.SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(h.SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(h.SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(h.SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(h.SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) = m.sku_group_clean WHERE h.date >= \'2026-04-01\' GROUP BY 1, 2, 3, 4 ), mp_sor_raw AS ( SELECT UPPER(TRIM(a.style)) AS sku_group, TRY_TO_DATE(NULLIF(TRIM(a.order_created_date), \'\'), \'YYYYMMDD\') AS date, TRY_TO_NUMBER(REPLACE(a.sales, \',\', \'\')) AS qty, TRY_TO_NUMBER(REPLACE(a.revenue, \',\', \'\')) AS revenue FROM snitch_db.maplemonk.S3_MYNTRA_B2B_GP a UNION ALL SELECT UPPER(TRIM(a.STYLE)) AS sku_group, TRY_TO_DATE(NULLIF(TRIM(a.order_date_key), \'\'), \'YYYYMMDD\') AS date, TRY_TO_NUMBER(REPLACE(a.units, \',\', \'\')) AS qty, TRY_TO_NUMBER(REPLACE(a.SP_Qty, \',\', \'\')) AS revenue FROM snitch_db.maplemonk.S3_Flipkart_B2B_GP a ), mp_sor AS ( SELECT DATE_TRUNC(\'MONTH\', s.date) AS month_date, lower(m.l1_category) AS l1_category, lower(m.category) AS category, \'MP\' AS channels, SUM(s.qty) AS sales_qty, SUM(s.revenue) AS sales_revenue, SUM(s.qty * COALESCE(m.sku_cogs, 0)) AS cogs FROM mp_sor_raw s LEFT JOIN meta_map m ON UPPER( IFF( UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1) ) ) = m.sku_group_clean WHERE s.date >= \'2026-04-01\' GROUP BY 1, 2, 3 ), sales_actual AS ( SELECT month_date, l1_category, category, channels, SUM(sales_qty) AS sales_qty, SUM(sales_revenue) AS sales_revenue, SUM(cogs) AS cogs FROM ( SELECT * FROM sales_actual_base UNION ALL SELECT * FROM mp_sor ) GROUP BY 1, 2, 3, 4 ), wh_inv_raw AS ( SELECT TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(\"Item SkuCode\"), POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) + 1 ) ) ) ) AS sku_group, SUM(inventory) AS inventory FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = CURRENT_DATE AND facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') GROUP BY 1 ), wh_inv AS ( SELECT lower(m.l1_category) AS l1_category, lower(m.category) AS category, SUM(w.inventory) AS wh_inv_qty FROM wh_inv_raw w LEFT JOIN meta_map m ON m.sku_group_clean = UPPER( IFF( UPPER(REPLACE(w.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(w.sku_group, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(w.sku_group, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(w.sku_group, \' \', \'\'), \'-.*$\', \'\') ) ) GROUP BY 1, 2 ), store_inv_raw AS ( SELECT o.sku_group, mm.l1_category, mm.category, COALESCE(o.S_UNITS,0) + COALESCE(o.JIT_S_UNITS,0) AS qty_s, COALESCE(o.M_UNITS,0) + COALESCE(o.JIT_M_UNITS,0) AS qty_m, COALESCE(o.L_UNITS,0) + COALESCE(o.JIT_L_UNITS,0) AS qty_l, COALESCE(o.XL_UNITS,0) + COALESCE(o.JIT_XL_UNITS,0) AS qty_xl, COALESCE(o.XL3_UNITS,0) + COALESCE(o.JIT_3XL_UNITS,0) AS qty_3xl, COALESCE(o.XL4_UNITS,0) + COALESCE(o.JIT_4XL_UNITS,0) AS qty_4xl, COALESCE(o.XL5_UNITS,0) + COALESCE(o.JIT_5XL_UNITS,0) AS qty_5xl, CASE WHEN COALESCE(o.S_UNITS,0) + COALESCE(o.JIT_S_UNITS,0) + COALESCE(o.M_UNITS,0) + COALESCE(o.JIT_M_UNITS,0) + COALESCE(o.L_UNITS,0) + COALESCE(o.JIT_L_UNITS,0) + COALESCE(o.XL_UNITS,0) + COALESCE(o.JIT_XL_UNITS,0) + COALESCE(o.XL3_UNITS,0) + COALESCE(o.JIT_3XL_UNITS,0) + COALESCE(o.XL4_UNITS,0) + COALESCE(o.JIT_4XL_UNITS,0) + COALESCE(o.XL5_UNITS,0) + COALESCE(o.JIT_5XL_UNITS,0) + COALESCE(o.XL6_UNITS,0) + COALESCE(o.JIT_6XL_UNITS,0) > 0 THEN COALESCE(o.XL6_UNITS,0) + COALESCE(o.JIT_6XL_UNITS,0) ELSE (COALESCE(o.inventory,0) + COALESCE(o.JIT_QTY,0)) END AS qty_6xl FROM snitch_db.maplemonk.offline_master_daily_report_1 o JOIN meta_map mm ON mm.sku_group_clean = UPPER( IFF( UPPER(REPLACE(o.SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(o.SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(o.SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(o.SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) WHERE o.date = CURRENT_DATE() ), store_inv AS ( SELECT lower(l1_category) AS l1_category, lower(category) AS category, SUM(qty_s + qty_m + qty_l + qty_xl + qty_3xl + qty_4xl + qty_5xl + qty_6xl) AS store_inv_qty FROM store_inv_raw GROUP BY 1, 2 ), inv_by_channel AS ( SELECT l1_category, category, \'Shopify\' AS channels, wh_inv_qty AS inv_qty FROM wh_inv UNION ALL SELECT l1_category, category, \'MP\' AS channels, wh_inv_qty AS inv_qty FROM wh_inv UNION ALL SELECT l1_category, category, \'Offline\' AS channels, store_inv_qty AS inv_qty FROM store_inv ), pipeline_l1_cat AS ( SELECT lower(L1_CATEGORY) AS l1_category, lower(CATEGORY) AS category, SUM(QTY) AS pipeline_left_qty, SUM(VALUE) AS pipeline_left_value, SUM(COGS) AS pipeline_cogs FROM snitch_db.maplemonk.production_pipeline_data_v2 WHERE NORMALIZED_SKU not IN (select distinct normalized_sku from snitch_db.maplemonk.SS27_plan_sheet1) GROUP BY 1, 2 ), pipeline_cat AS ( SELECT lower(CATEGORY) AS category, SUM(QTY) AS pipeline_left_qty, SUM(VALUE) AS pipeline_left_value, SUM(COGS) AS pipeline_cogs FROM snitch_db.maplemonk.production_pipeline_data_v2 WHERE NORMALIZED_SKU not IN (select distinct normalized_sku from snitch_db.maplemonk.SS27_plan_sheet1) GROUP BY 1 ), pipeline_l1_cat_curr_month_left AS ( SELECT lower(L1_CATEGORY) AS l1_category, lower(CATEGORY) AS category, SUM(QTY) AS curr_month_pipeline_left_qty, SUM(VALUE) AS curr_month_pipeline_left_value, SUM(COGS) AS curr_month_pipeline_left_cogs FROM snitch_db.maplemonk.production_pipeline_data_v2 WHERE DATE_TRUNC(\'month\', TRY_TO_DATE(FDD)) = DATE_TRUNC(\'month\', CURRENT_DATE()) and NORMALIZED_SKU not IN (select distinct normalized_sku from snitch_db.maplemonk.SS27_plan_sheet1) GROUP BY 1, 2 ), pipeline_cat_curr_month_left AS ( SELECT lower(CATEGORY) AS category, SUM(QTY) AS curr_month_pipeline_left_qty, SUM(VALUE) AS curr_month_pipeline_left_value, SUM(COGS) AS curr_month_pipeline_left_cogs FROM snitch_db.maplemonk.production_pipeline_data_v2 WHERE DATE_TRUNC(\'month\', TRY_TO_DATE(FDD)) = DATE_TRUNC(\'month\', CURRENT_DATE()) and NORMALIZED_SKU not IN (select distinct normalized_sku from snitch_db.maplemonk.SS27_plan_sheet1) GROUP BY 1 ), final_regular AS ( SELECT b.month_date, b.month, b.L1_category, b.category, b.channels, b.target_qty, COALESCE(s.sales_qty, 0) AS sales_qty, b.target_qty - COALESCE(s.sales_qty, 0) AS remaining_target_qty, COALESCE(ROUND(((b.target_qty - COALESCE(s.sales_qty, 0)) / NULLIF(b.target_qty, 0)) * 100), 0) AS pct_remaining_qty, b.target_revenue, COALESCE(s.sales_revenue, 0) AS sales_revenue, b.target_revenue - COALESCE(s.sales_revenue, 0) AS remaining_target_revenue, COALESCE(ROUND(((b.target_revenue - COALESCE(s.sales_revenue, 0)) / NULLIF(b.target_revenue, 0)) * 100), 0) AS pct_remaining_revenue, b.GM_target, COALESCE(s.cogs, 0) AS cogs_sold, ROUND((1 - (COALESCE(s.cogs, 0) / NULLIF(COALESCE(s.sales_revenue, 0), 0))) * 100, 2) AS gross_margin, CASE WHEN b.month_date = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN ROUND(b.target_qty * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) ELSE b.target_qty END AS target_qty_till_date, CASE WHEN b.month_date = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN ROUND(b.target_revenue * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) ELSE b.target_qty END AS target_revenue_till_date, ROUND(b.GM_target * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) AS target_gm_till_date, i.inv_qty, p.pipeline_left_qty, p.pipeline_left_value, p.pipeline_cogs, si.curr_month_pipeline_left_qty, si.curr_month_pipeline_left_value, si.curr_month_pipeline_left_cogs FROM Base_Data b LEFT JOIN sales_actual s ON b.month_date = s.month_date AND UPPER(TRIM(b.L1_category)) = UPPER(TRIM(s.L1_category)) AND UPPER(TRIM(b.category)) = UPPER(TRIM(s.category)) AND UPPER(TRIM(b.channels)) = UPPER(TRIM(s.channels)) LEFT JOIN inv_by_channel i ON UPPER(TRIM(b.L1_category)) = UPPER(TRIM(i.l1_category)) AND UPPER(TRIM(b.category)) = UPPER(TRIM(i.category)) AND UPPER(TRIM(b.channels)) = UPPER(TRIM(i.channels)) LEFT JOIN pipeline_l1_cat p ON UPPER(TRIM(b.L1_category)) = UPPER(TRIM(p.l1_category)) AND UPPER(TRIM(b.category)) = UPPER(TRIM(p.category)) LEFT JOIN pipeline_l1_cat_curr_month_left si ON UPPER(TRIM(b.L1_category)) = UPPER(TRIM(si.l1_category)) AND UPPER(TRIM(b.category)) = UPPER(TRIM(si.category)) WHERE lower(b.category) NOT IN (\'hoodies\', \'jackets\', \'sweaters\') ), winterwear_final AS ( SELECT COALESCE(b.month_date, s.month_date) AS month_date, b.month, NULL AS L1_category, COALESCE(b.category, s.category) AS category, COALESCE(b.channels, s.channels) AS channels, b.target_qty, COALESCE(s.sales_qty, 0) AS sales_qty, COALESCE(b.target_qty, 0) - COALESCE(s.sales_qty, 0) AS remaining_target_qty, COALESCE(ROUND(((COALESCE(b.target_qty,0) - COALESCE(s.sales_qty, 0)) / NULLIF(b.target_qty, 0)) * 100), 0) AS pct_remaining_qty, b.target_revenue, COALESCE(s.sales_revenue, 0) AS sales_revenue, COALESCE(b.target_revenue, 0) - COALESCE(s.sales_revenue, 0) AS remaining_target_revenue, COALESCE(ROUND(((COALESCE(b.target_revenue,0) - COALESCE(s.sales_revenue, 0)) / NULLIF(b.target_revenue, 0)) * 100), 0) AS pct_remaining_revenue, b.GM_target, COALESCE(s.cogs, 0) AS cogs_sold, ROUND((1 - (COALESCE(s.cogs, 0) / NULLIF(COALESCE(s.sales_revenue, 0), 0))) * 100, 2) AS gross_margin, CASE WHEN COALESCE(b.month_date, s.month_date) = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN ROUND(COALESCE(b.target_qty,0) * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) ELSE b.target_qty END AS target_qty_till_date, CASE WHEN COALESCE(b.month_date, s.month_date) = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN ROUND(COALESCE(b.target_revenue,0) * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) ELSE b.target_qty END AS target_revenue_till_date, ROUND(b.GM_target * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) AS target_gm_till_date, i.inv_qty, p.pipeline_left_qty, p.pipeline_left_value, p.pipeline_cogs, si.curr_month_pipeline_left_qty, si.curr_month_pipeline_left_value, si.curr_month_pipeline_left_cogs FROM (SELECT * FROM Base_Data WHERE lower(category) IN (\'hoodies\', \'jackets\', \'sweaters\')) b FULL OUTER JOIN (SELECT * FROM sales_actual WHERE category IN (\'hoodies\', \'jackets\', \'sweaters\')) s ON b.month_date = s.month_date AND UPPER(TRIM(b.category)) = UPPER(TRIM(s.category)) AND UPPER(TRIM(b.channels)) = UPPER(TRIM(s.channels)) LEFT JOIN inv_by_channel i ON UPPER(TRIM(COALESCE(b.category, s.category))) = UPPER(TRIM(i.category)) AND UPPER(TRIM(COALESCE(b.channels, s.channels))) = UPPER(TRIM(i.channels)) LEFT JOIN pipeline_cat p ON UPPER(TRIM(COALESCE(b.category, s.category))) = UPPER(TRIM(p.category)) LEFT JOIN pipeline_cat_curr_month_left si ON UPPER(TRIM(COALESCE(b.category, s.category))) = UPPER(TRIM(si.category)) ), ly_daily_sales AS ( SELECT lower(m.l1_category) AS l1_category, lower(m.category) AS category, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'MP\' WHEN type = \'Store\' THEN \'Offline\' END AS channels, h.date, SUM(h.gross_quantity) AS qty, SUM(h.gross_sales) AS revenue FROM snitch_db.maplemonk.horizontal_sales_categories h LEFT JOIN meta_map m ON UPPER( IFF( UPPER(REPLACE(h.SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(h.SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(h.SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(h.SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(h.SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) = m.sku_group_clean WHERE h.date >= DATEADD(year, -1, DATE_TRUNC(\'month\', CURRENT_DATE())) AND h.date < DATEADD(month, 1, DATEADD(year, -1, DATE_TRUNC(\'month\', CURRENT_DATE()))) GROUP BY 1, 2, 3, 4 ), ly_split AS ( SELECT l1_category, category, channels, SUM(CASE WHEN DAY(date) <= DAY(CURRENT_DATE()) THEN qty ELSE 0 END) AS ly_mtd_qty, SUM(qty) AS ly_full_qty, SUM(CASE WHEN DAY(date) <= DAY(CURRENT_DATE()) THEN revenue ELSE 0 END) AS ly_mtd_revenue, SUM(revenue) AS ly_full_revenue FROM ly_daily_sales GROUP BY 1, 2, 3 ), sales_projection_current_month AS ( SELECT cur.l1_category, cur.category, cur.channels, CURRENT_DATE() AS as_of_date, DAY(CURRENT_DATE()) AS as_of_day, DAY(LAST_DAY(CURRENT_DATE())) AS days_in_month, DAY(LAST_DAY(CURRENT_DATE())) - DAY(CURRENT_DATE()) AS days_remaining, cur.sales_qty AS actual_mtd_qty, cur.sales_revenue AS actual_mtd_revenue, ly.ly_mtd_qty, ly.ly_full_qty, ly.ly_mtd_revenue, ly.ly_full_revenue, COALESCE(ly.ly_full_qty / NULLIF(ly.ly_mtd_qty, 0), DAY(LAST_DAY(CURRENT_DATE())) / DAY(CURRENT_DATE())) AS qty_scale_factor, COALESCE(ly.ly_full_revenue / NULLIF(ly.ly_mtd_revenue, 0), DAY(LAST_DAY(CURRENT_DATE())) / DAY(CURRENT_DATE())) AS revenue_scale_factor, ROUND(cur.sales_qty * COALESCE(ly.ly_full_qty / NULLIF(ly.ly_mtd_qty, 0), DAY(LAST_DAY(CURRENT_DATE())) / DAY(CURRENT_DATE())) ) AS projected_full_month_qty, ROUND(cur.sales_revenue * COALESCE(ly.ly_full_revenue / NULLIF(ly.ly_mtd_revenue, 0), DAY(LAST_DAY(CURRENT_DATE())) / DAY(CURRENT_DATE())) ) AS projected_full_month_revenue, ROUND(cur.sales_qty * COALESCE(ly.ly_full_qty / NULLIF(ly.ly_mtd_qty, 0), DAY(LAST_DAY(CURRENT_DATE())) / DAY(CURRENT_DATE())) - cur.sales_qty ) AS projected_remaining_qty, ROUND(cur.sales_revenue * COALESCE(ly.ly_full_revenue / NULLIF(ly.ly_mtd_revenue, 0), DAY(LAST_DAY(CURRENT_DATE())) / DAY(CURRENT_DATE())) - cur.sales_revenue ) AS projected_remaining_revenue FROM sales_actual cur LEFT JOIN ly_split ly ON UPPER(TRIM(cur.l1_category)) = UPPER(TRIM(ly.l1_category)) AND UPPER(TRIM(cur.category)) = UPPER(TRIM(ly.category)) AND UPPER(TRIM(cur.channels)) = UPPER(TRIM(ly.channels)) WHERE cur.month_date = DATE_TRUNC(\'month\', CURRENT_DATE()) ), next_3m_target_calc AS ( SELECT l1_category, category, channels, target_qty, target_revenue, GM_target, DAY(LAST_DAY(month_date)) AS days_in_month, GREATEST( 0, DATEDIFF( day, GREATEST(month_date, CURRENT_DATE()), LEAST(LAST_DAY(month_date), DATEADD(day, -1, DATEADD(month, 3, CURRENT_DATE()))) ) + 1 ) AS overlap_days FROM Base_Data WHERE month_date BETWEEN DATE_TRUNC(\'month\', CURRENT_DATE()) AND DATE_TRUNC(\'month\', DATEADD(day, -1, DATEADD(month, 3, CURRENT_DATE()))) ), next_3m_target AS ( SELECT l1_category, category, channels, CURRENT_DATE() AS window_start, DATEADD(day, -1, DATEADD(month, 3, CURRENT_DATE())) AS window_end, SUM(target_qty * overlap_days / days_in_month) AS target_qty_next_3m, SUM(target_revenue * overlap_days / days_in_month) AS target_revenue_next_3m, SUM(GM_target * overlap_days) / NULLIF(SUM(overlap_days), 0) AS avg_gm_target_next_3m FROM next_3m_target_calc WHERE overlap_days > 0 GROUP BY 1, 2, 3 ), combined AS ( SELECT * FROM final_regular UNION ALL SELECT * FROM winterwear_final ) SELECT c.*, proj.as_of_date, proj.as_of_day, proj.days_in_month AS proj_days_in_month, proj.days_remaining AS proj_days_remaining, proj.actual_mtd_qty, proj.actual_mtd_revenue, proj.qty_scale_factor, proj.revenue_scale_factor, proj.projected_full_month_qty, proj.projected_full_month_revenue, proj.projected_remaining_qty, proj.projected_remaining_revenue, n3.window_start AS next_3m_window_start, n3.window_end AS next_3m_window_end, n3.target_qty_next_3m, n3.target_revenue_next_3m, n3.avg_gm_target_next_3m FROM combined c LEFT JOIN sales_projection_current_month proj ON UPPER(TRIM(COALESCE(c.L1_category, \'\'))) = UPPER(TRIM(COALESCE(proj.l1_category, \'\'))) AND UPPER(TRIM(c.category)) = UPPER(TRIM(proj.category)) AND UPPER(TRIM(c.channels)) = UPPER(TRIM(proj.channels)) AND c.month_date = DATE_TRUNC(\'month\', CURRENT_DATE()) LEFT JOIN next_3m_target n3 ON UPPER(TRIM(COALESCE(c.L1_category, \'\'))) = UPPER(TRIM(COALESCE(n3.l1_category, \'\'))) AND UPPER(TRIM(c.category)) = UPPER(TRIM(n3.category)) AND UPPER(TRIM(c.channels)) = UPPER(TRIM(n3.channels)) ORDER BY c.month_date, c.L1_category, c.category, c.channels;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            